import { ARTWORK_ASSETS, type ArtworkAssetSet } from './artworkAssets';
import data from './artworks.json';
import type { CategoryId } from './categories';
import type { Artwork, ArtworkLevel } from './types';

// Read-only access to the generated artwork manifest (artworks.json / artworkAssets.ts are
// generated by `npm run art:build`, never edited by hand).

export const ARTWORKS: readonly Artwork[] = data as Artwork[];

const BY_ID = new Map(ARTWORKS.map((a) => [a.id, a]));

export function getArtwork(id: string): Artwork | undefined {
  return BY_ID.get(id);
}

export function getArtworkAssets(id: string): ArtworkAssetSet | undefined {
  return ARTWORK_ASSETS[id];
}

/** Artworks of a category in manifest order, optionally only one level. */
export function artworksIn(category: CategoryId, level?: ArtworkLevel): Artwork[] {
  return ARTWORKS.filter((a) => a.category === category && (!level || a.level === level));
}

/** Picture used as the category icon: the first easy artwork, else the first one, else null. */
export function categoryIcon(category: CategoryId): Artwork | null {
  const all = artworksIn(category);
  return all.find((a) => a.level === 'easy') ?? all[0] ?? null;
}
